// Generator for the ASUS monitor module device table.
// Usage: node scripts/openrgb/port-asus-monitor-devices.mjs <openrgb-root> <commit>
// Reads AsusMonitorControllerDetect.cpp and regenerates
// modules/asus-monitor/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'AsusMonitorController');
const detect = fs.readFileSync(path.join(family, 'AsusMonitorControllerDetect.cpp'), 'utf8');
const headerText = fs
  .readdirSync(family)
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');

const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+([A-Z][A-Z0-9_]+)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.ASUS_VID == null) throw new Error('ASUS_VID not found');
const n = (s) => constants[s.trim()] ?? Number.parseInt(s.trim(), 16);

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR[A-Z_]*\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*ASUS_VID\s*,\s*([A-Z][A-Z0-9_]+(?:_PID))\s*,\s*(0x[0-9A-Fa-f]+|\d+)\s*,\s*(0x[0-9A-Fa-f]+)\s*,\s*(0x[0-9A-Fa-f]+)\s*\)/g,
)) {
  const pid = n(m[3]);
  if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[3]} in detector row ${m[1]}`);
  rows.push({
    name: m[1],
    handler: m[2],
    vid: constants.ASUS_VID,
    pid,
    interface: m[4].startsWith('0x') ? Number.parseInt(m[4].slice(2), 16) : Number.parseInt(m[4], 10),
    usagePage: Number.parseInt(m[5].slice(2), 16),
    usage: Number.parseInt(m[6].slice(2), 16),
  });
}
if (rows.length === 0) throw new Error('no ASUS monitor detectors parsed');

const out = path.join(process.cwd(), 'modules', 'asus-monitor', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-asus-monitor-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: 0x${d.usage.toString(16)} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} ASUS monitor HID detectors`);